SELECT trial_id,
   (detail ->> 'judge_model'::text) AS judge_model
  FROM evals.eval_trial_detail d;

WITH x AS (
        SELECT d.detail
          FROM evals.eval_trial_detail d
       )
SELECT (detail ->> 'summary'::text) AS s
  FROM x;

SELECT (detail ->> 'summary'::text) AS s
  FROM ( SELECT d.detail
          FROM evals.eval_trial_detail d) s;

SELECT (e.value ->> 'feedback'::text) AS f
  FROM evals.eval_trial_detail d,
   LATERAL jsonb_array_elements((d.detail -> 'dimensions'::text)) e(value);

SELECT e.value AS f
  FROM evals.eval_trial_detail d,
   LATERAL jsonb_array_elements((d.detail -> 'dimensions'::text)) e(value);

SELECT to_jsonb(e.value) AS f
  FROM evals.eval_trial_detail d,
   LATERAL jsonb_array_elements((d.detail -> 'dimensions'::text)) e(value);
